var mf=System.Linq.Enumerable.First(UnityEngine.Object.FindFirstObjectByType<TownStudy.Builder.BuilderController>().GetComponentsInChildren<UnityEngine.MeshFilter>(),m=>m.name.StartsWith("Window")&&m.transform.position.z<-.1f);return mf.name+" pos="+mf.transform.position+" rot="+mf.transform.eulerAngles+" uv="+string.Join(";",mf.sharedMesh.uv)+" vertices="+string.Join(";",mf.sharedMesh.vertices);
